import { existsSync as existsSync5 } from "fs";
import fs5 from "fs/promises";
import JSONC from "comment-json";
import { join as join5 } from "path";
function addAliasToTsConfig(directory) {
  return {
    name: "Add alias to tsconfig",
    async run() {
      const tsConfigPath = join5(directory, "tsconfig.json");
      if (!existsSync5(tsConfigPath)) {
        return {
          status: "skipped",
          message: "tsconfig.json not found"
        };
      }
      const tsConfig = JSONC.parse(await fs5.readFile(tsConfigPath, "utf-8"));
      if (!tsConfig.compilerOptions) {
        tsConfig.compilerOptions = {};
      }
      if (!tsConfig.compilerOptions.paths) {
        tsConfig.compilerOptions.paths = {};
      }
      const alias = tsConfig.compilerOptions.paths["content-collections"];
      if (alias) {
        const [first] = alias;
        if (first) {
          if (first === "./.content-collections/generated") {
            return {
              status: "skipped",
              message: "content-collections alias already exists"
            };
          } else {
            return {
              status: "error",
              message: "content-collections alias already exists and is pointing to a different path"
            };
          }
        }
      }
      tsConfig.compilerOptions.paths["content-collections"] = [
        "./.content-collections/generated"
      ];
      await fs5.writeFile(tsConfigPath, JSONC.stringify(tsConfig, null, 2));
      return {
        status: "changed",
        message: "Added content-collections alias to tsconfig"
      };
    }
  };
}

